mapper.update:
/* com.heeji.picket.mapper.UserMapper.update */
UPDATE  USER

    UPDATE_DATE = NOW()
    , PASSWORD = #{password}
    , ROLE = #{role}
    , NAME = #{name}
    , PHONE_NUMBER = #{phoneNumber}
    , ADDRESS = #{address}
    , DETAIL_ADDRESS = #{detailAddress}
    , IS_DELETED = #{isDeleted}
    , DELETE_DATE = #{deleteDate}
    , PROVIDER_TYPE = #{providerType}
    , KAKAO_ON = #{kakaoOn}
    , EMAIL_ON = #{emailOn}

WHERE   1 = 1
AND     EMAIL = #{email}

mapper.delete:
/* com.heeji.picket.mapper.UserMapper.delete */
DELETE FROM USER
WHERE       1 = 1
AND         EMAIL = #{email}
